package com.way2jobs.scraper;
import com.way2jobs.scraper.config.ScraperProperties; import com.way2jobs.scraper.dto.ScraperRunResult; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/scraper") @RequiredArgsConstructor public class ScraperController {private final JobScraperService service;private final ScraperProperties props;@PostMapping("/run") public ScraperRunResult run(){return service.run();}@GetMapping("/status")public Map<String,Object> status(){Map<String,Object> r=new LinkedHashMap<>();r.put("enabled",props.isEnabled());r.put("scheduleEnabled",props.isScheduleEnabled());r.put("cron",props.getCron());r.put("running",service.isRunning());r.put("maxJobsPerRun",props.getMaxJobsPerRun());r.put("sources",props.getSources());r.put("lastRun",service.getLastResult());return r;}}
